#include <stdio.h>

int main(void) {
    int A, L;
    if (scanf("%d %d", &A, &L) != 2) return 0;

    int n;
    if (scanf("%d", &n) != 1) return 0;

    int bestId = -1;
    long long bestArea = 0;

    for (int i = 1; i <= n; i++) {
        int x, y;
        scanf("%d %d", &x, &y);

        /* A foto cabe se couber na moldura em alguma orientação
           (a moldura pode ser rotacionada) */
        int fits = (A <= x && L <= y) || (A <= y && L <= x);

        if (fits) {
            long long area = (long long)x * y;
            /* Como A*L é fixo, minimizar o desperdício equivale a
               minimizar a área da moldura; empates ficam com o
               menor identificador (comparação estrita + ordem crescente) */
            if (bestId == -1 || area < bestArea) {
                bestArea = area;
                bestId = i;
            }
        }
    }

    printf("%d\n", bestId);
    return 0;
}
